const b = $json.body || $json;
let raw = String(b.website || b.domain || b.url || '').trim();
if (!raw) raw = 'https://sleepyowl.co';
if (!/^https?:\/\//i.test(raw)) raw = 'https://' + raw;
const m = raw.match(/^https?:\/\/([^\/?#:]+)/i);
if (!m) throw new Error('Could not read that website address: ' + raw);
const host = m[1].toLowerCase().replace(/^www\./, '');
const base = 'https://' + host;
const cfg = {
  run_id: 'RUN-' + Date.now(),
  domain: host,
  owner_email: 'naikanant381@gmail.com',
  seller: 'Intelligence. We build custom AI automation systems for Indian businesses on n8n, such as outbound research engines and vendor comparison desks, delivered in weeks rather than months. Proof point: we ship a working production system live every Saturday with our operator cohort. Sender: Anant, Founder.',
  signature: 'Anant\nFounder, Intelligence\nnaikanant381@gmail.com',
  postal: 'Intelligence, India',
  banned: ['hope this email finds you','quick question','circle back','reach out','touch base','synergy','revolutionary','game changer','i wanted to','i came across your','leverage','seamless','cutting edge','at your earliest convenience','let me know if','delve','elevate','unlock']
};
const pages = [base, base + '/about', base + '/pricing', base + '/careers', base + '/contact'];
return pages.map(u => ({ json: Object.assign({}, cfg, { target_url: u, pages_tried: pages.length }) }));

const cfg = $('1 Setup').first().json;
const parts = [];
for (const it of $input.all()) {
  const t = it.json.data || it.json.body || it.json.text || '';
  const u = it.json.target_url || '';
  if (typeof t === 'string' && t.length > 300 && !/^\s*(404|not found)/i.test(t)) {
    parts.push('### SOURCE: ' + u + '\n' + t.slice(0, 12000));
  }
}
if (!parts.length) throw new Error('Could not read any page on ' + cfg.domain + '. Nothing is written without evidence.');
return [{ json: Object.assign({}, cfg, { pages_ok: parts.length, corpus: parts.join('\n\n').slice(0, 45000) }) }];

function parse(raw) {
  let t = String(raw || '').replace(/```json/gi, '').replace(/```/g, '').trim();
  const s = t.indexOf('{'), e = t.lastIndexOf('}');
  if (s === -1 || e === -1) throw new Error('The Researcher did not return JSON.');
  t = t.slice(s, e + 1).replace(/,(\s*[}\]])/g, '$1');
  return JSON.parse(t);
}
const prev = $('3 Build evidence').first().json;
const c = $json && $json.candidates && $json.candidates[0];
const txt = c && c.content && c.content.parts && c.content.parts[0] && c.content.parts[0].text;
if (!txt) throw new Error('Researcher returned nothing. Usually the Gemini free tier rate limit. Wait a minute and run again.');
const d = parse(txt);
const hay = String(prev.corpus || '').toLowerCase().replace(/\s+/g, ' ');
const norm = s => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();
const dropped = [];
d.notable_facts = (d.notable_facts || []).filter(x => {
  const q = norm(x.evidence);
  const ok = q.length >= 8 && hay.indexOf(q) !== -1;
  if (!ok) dropped.push(x.fact || 'unnamed claim');
  return ok;
});
d.contact_emails = (d.contact_emails || []).filter(e => hay.indexOf(norm(e)) !== -1);
const confidence = Math.min(100, (d.notable_facts.length * 18) + (prev.pages_ok * 6));
return [{ json: Object.assign({}, prev, { dossier: d, dropped: dropped, confidence: confidence }) }];

function parse(raw) {
  let t = String(raw || '').replace(/```json/gi, '').replace(/```/g, '').trim();
  const s = t.indexOf('{'), e = t.lastIndexOf('}');
  if (s === -1 || e === -1) throw new Error('The Fit Scorer did not return JSON.');
  t = t.slice(s, e + 1).replace(/,(\s*[}\]])/g, '$1');
  return JSON.parse(t);
}
const prev = $('5 Dossier and evidence lock').first().json;
const c = $json && $json.candidates && $json.candidates[0];
const txt = c && c.content && c.content.parts && c.content.parts[0] && c.content.parts[0].text;
if (!txt) throw new Error('Fit Scorer returned nothing. Usually the Gemini free tier rate limit.');
const s = parse(txt);
const sum = (s.awarded_values || []).reduce((a, b) => a + (Number(b) || 0), 0);
s.arithmetic_checks_out = (sum === Number(s.recheck_total));
return [{ json: Object.assign({}, prev, { scoring: s }) }];

function parse(raw) {
  let t = String(raw || '').replace(/```json/gi, '').replace(/```/g, '').trim();
  const s = t.indexOf('{'), e = t.lastIndexOf('}');
  if (s === -1 || e === -1) throw new Error('The Pain Finder did not return JSON.');
  t = t.slice(s, e + 1).replace(/,(\s*[}\]])/g, '$1');
  return JSON.parse(t);
}
const prev = $('8 Score the fit').first().json;
const c = $json && $json.candidates && $json.candidates[0];
const txt = c && c.content && c.content.parts && c.content.parts[0] && c.content.parts[0].text;
if (!txt) throw new Error('Pain Finder returned nothing. Usually the Gemini free tier rate limit.');
const out = parse(txt);
const norm = s => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();
const d = prev.dossier || {};
const bits = [prev.corpus || ''];
for (const f of (d.notable_facts || [])) bits.push((f.fact || '') + ' ' + (f.evidence || ''));
bits.push(d.what_they_sell, d.who_they_sell_to, d.one_liner, d.company_name, d.location_signals, d.currency_signals, d.team_signals, d.hiring_signals, d.funding_signals, d.online_signals, d.manual_process_signals);
const pool = norm(bits.filter(Boolean).join(' || '));
const dropped = [];
const pains = (out.pains || []).filter(p => {
  const a = norm(p.anchor);
  if (a.length < 8) { dropped.push(p.pain || 'unnamed'); return false; }
  if (pool.indexOf(a) !== -1) return true;
  const tk = a.split(' ').filter(w => w.length > 3);
  if (tk.length && tk.filter(w => pool.indexOf(w) !== -1).length / tk.length >= 0.7) return true;
  dropped.push(p.pain || 'unnamed');
  return false;
});
if (!pains.length) throw new Error('No pain could be anchored to evidence on their website, so nothing was written. This is the system refusing, not failing.');
return [{ json: Object.assign({}, prev, { pains: pains, pains_dropped: dropped }) }];

const scored = $('8 Score the fit').first().json;
const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const blocked = scored.scoring.disqualified || scored.scoring.band === 'D';
let base = scored, emails = [], failures = [];

if (!blocked) {
  base = $('11 Anchor the pains').first().json;
  const c = $json && $json.candidates && $json.candidates[0];
  const txt = c && c.content && c.content.parts && c.content.parts[0] && c.content.parts[0].text;
  if (!txt) {
    // The writer was throttled. Report it cleanly with the research intact
    // rather than killing a run that already produced a usable dossier.
    failures.push('The Sequence Writer did not return. Usually the Gemini free tier rate limit. The research below is complete, only the emails are missing. Run again in a minute.');
  } else {
    let t = String(txt).replace(/```json/gi, '').replace(/```/g, '').trim();
    const a = t.indexOf('{'), b = t.lastIndexOf('}');
    if (a === -1 || b === -1) {
      failures.push('The Sequence Writer did not return valid JSON.');
    } else {
      emails = JSON.parse(t.slice(a, b + 1).replace(/,(\s*[}\]])/g, '$1')).emails || [];
    }
  }

  const hay = String(base.corpus || '').toLowerCase().replace(/\s+/g, ' ');
  const banned = (base.banned || []).map(p => String(p).toLowerCase());
  const limits = { 1: [60, 130], 2: [40, 90], 3: [40, 90] };
  for (const e of emails) {
    const body = String(e.body || '');
    const low = (e.subject + ' ' + body).toLowerCase();
    const wc = body.trim().split(/\s+/).filter(Boolean).length;
    const lim = limits[e.email_no] || [40, 120];
    const tag = 'Email ' + e.email_no + ': ';
    if (wc < lim[0] || wc > lim[1]) failures.push(tag + 'word count ' + wc + ', must be ' + lim[0] + ' to ' + lim[1]);
    if (String(e.subject || '').trim().split(/\s+/).length > 7) failures.push(tag + 'subject over 7 words');
    if ((body.match(/\?/g) || []).length > 1) failures.push(tag + 'more than one question mark');
    if (/—|–/.test(body + e.subject)) failures.push(tag + 'contains a dash character');
    if (/\[[^\]]+\]/.test(body)) failures.push(tag + 'unfilled placeholder');
    for (const p of banned) if (p && low.indexOf(p) !== -1) failures.push(tag + 'banned phrase ' + p);
    if (e.email_no === 1) {
      const det = String(e.personalisation_detail || '').toLowerCase().replace(/\s+/g, ' ').trim();
      if (det.length < 8) failures.push(tag + 'no personalisation detail');
      else if (hay.indexOf(det) === -1) failures.push(tag + 'personalisation detail is not on their website');
    }
  }
  if ((JSON.stringify(emails).match(/https?:\/\//g) || []).length > 1) failures.push('More than one link in the sequence');
  if (failures.length) emails = [];
}

const found = (base.dossier && base.dossier.contact_emails) || [];
const generic = found.filter(e => /^(info|hello|contact|sales|support|help)@/i.test(e));
const recipient = generic[0] || found[0] || '';
const note = recipient ? 'Found published on their website' : 'No address published, so the draft is blank. We never guess one.';
const finished = emails.map(e => Object.assign({}, e, { body: e.body + '\n\n' + base.signature + '\n\n--\nNot relevant? Reply with no thanks and I will not write again.\n' + base.postal }));

const sc = scored.scoring.scorecard || [];
const isX = r => String(r.signal_group || '').toLowerCase() === 'exclusion';
const hit = sc.filter(r => r.matched && !isX(r));
const miss = sc.filter(r => !r.matched && !isX(r));
const xr = sc.filter(isX);
const rows = hit.map(r => '<tr><td style="padding:8px;border-bottom:1px solid #eee;font-family:monospace;color:#1B7E42"><b>' + esc(r.rule_id) + '</b></td><td style="padding:8px;border-bottom:1px solid #eee">' + esc(r.criterion || r.signal_group) + '</td><td style="padding:8px;border-bottom:1px solid #eee;text-align:right;color:#1B7E42"><b>+' + esc(r.points_awarded) + '</b></td><td style="padding:8px;border-bottom:1px solid #eee;color:#555;font-size:12px">' + esc(r.evidence) + '</td></tr>').join('');
const emailHtml = finished.map(e => '<div style="margin:10px 0;padding:12px;background:#faf9f5;border-left:3px solid #1B7E42"><b>Email ' + esc(e.email_no) + ': ' + esc(e.subject) + '</b><pre style="white-space:pre-wrap;font-family:inherit;margin:8px 0 0;font-size:13px">' + esc(e.body) + '</pre></div>').join('');
const banner = blocked ? '<div style="background:#b00;color:#fff;padding:12px;margin:10px 0"><b>Disqualified. No outreach was written.</b><br>' + esc(scored.scoring.disqualify_rule || ('Band ' + scored.scoring.band)) + '</div>' : (failures.length ? '<div style="background:#fff4e5;border-left:3px solid #E67E22;padding:12px;margin:10px 0"><b>No drafts were created on this run.</b><br>' + esc(failures.join('; ')) + '</div>' : '');
const html = '<table width="100%" cellpadding="0" cellspacing="0" style="background:#fffdf7;font-family:Helvetica,Arial,sans-serif"><tr><td align="center"><table width="680" cellpadding="0" cellspacing="0">' +
'<tr><td style="background:#000;padding:18px 20px"><span style="color:#c8f31d;font-size:18px;font-weight:bold">HOI</span> <span style="color:#fff;font-size:14px">Account Research</span></td></tr>' +
'<tr><td style="padding:18px 20px">' + banner +
'<h2 style="margin:10px 0 4px">' + esc(base.dossier.company_name) + '</h2>' +
'<p style="color:#555;margin:0 0 10px">' + esc(base.dossier.what_they_sell) + '</p>' +
'<p style="font-size:22px;margin:10px 0"><b>' + esc(scored.scoring.final_score) + ' of 100</b> <span style="background:#1B7E42;color:#fff;padding:3px 10px;font-size:14px">Band ' + esc(scored.scoring.band) + '</span></p>' +
'<p style="color:#333;margin:0 0 14px">' + esc(scored.scoring.verdict) + '</p>' +
'<h3 style="margin-bottom:6px">How the score was built</h3><table width="100%" cellpadding="0" cellspacing="0" style="font-size:13px;border-collapse:collapse"><tr style="background:#000;color:#fff"><th align="left" style="padding:7px">Rule</th><th align="left" style="padding:7px">What it rewards</th><th align="right" style="padding:7px">Points</th><th align="left" style="padding:7px">Evidence found</th></tr>' + rows +
'<tr style="background:#f2f2ee"><td colspan="2" style="padding:8px"><b>Total</b></td><td style="padding:8px;text-align:right"><b>' + esc(scored.scoring.final_score) + '</b></td><td></td></tr></table>' +
'<p style="color:#666;font-size:13px;margin:10px 0 2px"><b>Checked and did not score:</b> ' + (miss.length ? esc(miss.map(r => r.rule_id).join(', ')) + ' (' + miss.length + ' rules, nothing on their site supported them)' : 'every rule matched') + '</p>' +
'<p style="color:#666;font-size:13px;margin:2px 0 14px"><b>Exclusions:</b> ' + (xr.filter(r => r.matched).length ? 'TRIGGERED' : xr.length + ' checked, all clear') + '</p>' +
'<p style="color:#666;font-size:13px"><b>Arithmetic:</b> ' + esc(JSON.stringify(scored.scoring.awarded_values)) + ' sums to ' + esc(scored.scoring.recheck_total) + (scored.scoring.arithmetic_checks_out ? ', which matches the score.' : ', which does NOT match. Flagged.') + '</p>' +
'<h3>What we could not find</h3><p style="color:#555">Confidence ' + esc(base.confidence) + ' percent. ' + ((base.dossier.not_found || []).length ? 'No evidence on their site for: ' + esc((base.dossier.not_found || []).join(', ')) + '.' : 'Nothing flagged.') + '</p>' +
(blocked ? '' : '<h3>Pains</h3><ul>' + ((base.pains || []).map(p => '<li style="margin:8px 0"><b>' + esc(p.pain) + '</b><br><span style="color:#555;font-size:13px">anchored to: ' + esc(p.anchor) + '</span></li>').join('') || '<li>None</li>') + '</ul>') +
(finished.length ? '<h3>The sequence</h3>' + emailHtml + '<h3>Recipient</h3><p>' + esc(recipient || 'blank') + '<br><span style="color:#555">' + esc(note) + '</span></p>' : '') +
'<h3 style="color:#b00">Run report</h3><ul style="color:#555;font-size:13px"><li>Pages read: ' + esc(base.pages_ok) + ' of ' + esc(base.pages_tried) + '</li><li>Claims deleted by the evidence lock: ' + ((base.dropped || []).length ? esc((base.dropped || []).join(', ')) : 'none') + '</li><li>Pains dropped: ' + ((base.pains_dropped || []).length ? esc((base.pains_dropped || []).join(', ')) : 'none') + '</li><li>Quality failures: ' + (failures.length ? esc(failures.join('; ')) : 'none') + '</li><li>Drafts created: ' + finished.length + '</li></ul>' +
'<p style="color:#888;font-size:12px;border-top:1px solid #ddd;padding-top:10px">Automated research. Verify before sending.</p></td></tr></table></td></tr></table>';

return [{ json: Object.assign({}, base, { scoring: scored.scoring, emails: finished, recipient: recipient, recipient_note: note, quality_failures: failures, blocked: blocked, dossier_html: html }) }];
